import rawData from '../ratingAreas/data/rating-areas.json'
import { resolveZip } from './planSearch'

/**
 * Geographic rating areas: which counties (or 3-digit zips) make up each area, and the reverse.
 * The crosswalk is static reference data generated by scripts/build-rating-areas.ts from CMS and
 * Census; the query functions are pure over it so routes stay thin and tests use a small fixture.
 */

export type County = { fips: string; name: string }
export type Area = {
  id: string
  state: string
  areaNumber: number
  basis: 'county' | 'zip3'
  counties: County[]
  zip3: string[]
}
export type StateInfo = { name: string; basis: 'county' | 'zip3' | 'mixed'; areaIds: string[] }
export type RatingAreaData = {
  planYear: number
  generatedAt: string
  source: string
  states: Record<string, StateInfo>
  areas: Record<string, Area>
  countyToArea: Record<string, string>
  zip3ToArea: Record<string, string>
}

export const DATA = rawData as RatingAreaData

/** "mn7", "MN-07", "MN7" → "MN07"; anything that is not a state code plus 1–2 digits → null. */
export function normalizeAreaId(raw: string): string | null {
  const m = raw.trim().toUpperCase().match(/^([A-Z]{2})[-\s]?0*(\d{1,2})$/)
  if (!m) return null
  return `${m[1]}${m[2].padStart(2, '0')}`
}

export function getArea(d: RatingAreaData, id: string): Area | null {
  return d.areas[id] ?? null
}

export type StateAreas = {
  state: string
  stateName: string
  basis: StateInfo['basis']
  areas: { id: string; areaNumber: number; countyCount: number }[]
}

export function areasInState(d: RatingAreaData, state: string): StateAreas | null {
  const st = state.trim().toUpperCase()
  const info = d.states[st]
  if (!info) return null
  return {
    state: st,
    stateName: info.name,
    basis: info.basis,
    areas: info.areaIds.map((id) => ({
      id,
      areaNumber: d.areas[id].areaNumber,
      countyCount: d.areas[id].counties.length,
    })),
  }
}

export function areaIdForCountyFips(d: RatingAreaData, fips: string): string | null {
  return d.countyToArea[fips.trim()] ?? null
}

export function areaIdForZip3(d: RatingAreaData, state: string, zip3: string): string | null {
  return d.zip3ToArea[`${state.trim().toUpperCase()}:${zip3}`] ?? null
}

export function statesOverview(d: RatingAreaData) {
  return Object.entries(d.states).map(([state, info]) => ({
    state,
    stateName: info.name,
    basis: info.basis,
    areaCount: info.areaIds.length,
  }))
}

export type ZipRatingArea = { zip: string; county: County; state: string; area: Area }

/** Reverse by zip: resolve the zip to a county (Ideon, cached), then county → area, zip3 as fallback. */
export async function ratingAreaForZip(zip: string): Promise<ZipRatingArea | null> {
  const county = await resolveZip(zip)
  const areaId =
    areaIdForCountyFips(DATA, county.fipsCode) ?? areaIdForZip3(DATA, county.state, zip.slice(0, 3))
  const area = areaId ? getArea(DATA, areaId) : null
  if (!area) return null
  // Prefer the crosswalk's county name so the reverse view matches the forward one; the Ideon
  // name ("Olmsted County") carries a suffix the bare crosswalk name ("Olmsted") does not.
  const name = area.counties.find((c) => c.fips === county.fipsCode)?.name ?? county.countyName ?? ''
  return { zip, county: { fips: county.fipsCode, name }, state: county.state, area }
}

/** One stable county-grained CSV schema for area and state exports. */
export const COUNTY_CSV_HEADERS = [
  'rating_area_id',
  'state',
  'state_name',
  'area_number',
  'county_fips',
  'county_name',
  'zip3',
]

/** Area → CSV rows: one per county, or one per 3-digit zip for a zip-based area. */
export function areaCountyRows(d: RatingAreaData, area: Area): (string | number)[][] {
  const stateName = d.states[area.state]?.name ?? ''
  const base = [area.id, area.state, stateName, area.areaNumber]
  if (area.counties.length === 0 && area.zip3.length > 0) {
    return area.zip3.map((z) => [...base, '', '', z])
  }
  return area.counties.map((c) => [...base, c.fips, c.name, ''])
}
